using System;
using UnityEngine;
namespace AthenHill
{
    /// Brann's guided first job: his lines as an asset (Audio/ElevenLabs/Bench/Tutor/BenchTutorLines.asset), generated by
    /// BenchTutorInstall20261121 from art/steady_hands_bench_20261120/audio/tutor/lines.json (tutor agent, 21 Nov 2026).
    /// Triggers are the tutor's own: tutor.welcome, tutor.step:ID, tutor.action:ID:KEY, tutor.verb:TEACH, tutor.recovery:ID.
    public class BenchTutorLines : ScriptableObject
    {
        [Serializable] public class Line
        {
            public string id = "", kind = "", step = "", verb = "", key = "", trigger = "";
            public int stage = -1;
            [TextArea] public string text = "";
            public AudioClip clip;
        }
        public Line[] lines = new Line[0];
        /// The on-screen instruction table (audio/tutor/instructions.json, Carl 21 Nov: "idiot proof"): one plain instruction per
        /// action ("s1.screw_a:turn"), names of parts, tools and shots, the prefixes and the refusal captions.
        [Serializable] public class Pair { public string key = "", value = ""; }
        public Pair[] actions = new Pair[0], names = new Pair[0], tools = new Pair[0], shots = new Pair[0], prefix = new Pair[0], refused = new Pair[0];
        System.Collections.Generic.Dictionary<string, string> index;
        /// table: actions, names, tools, shots, prefix, refused. Null when absent.
        public string Text(string table, string key)
        {
            if (string.IsNullOrEmpty(key)) return null;
            if (index == null)
            {
                index = new System.Collections.Generic.Dictionary<string, string>();
                void Add(string t, Pair[] ps) { if (ps != null) foreach (var x in ps) if (x != null && !string.IsNullOrEmpty(x.key)) index[t + "|" + x.key] = x.value; }
                Add("actions", actions); Add("names", names); Add("tools", tools); Add("shots", shots); Add("prefix", prefix); Add("refused", refused);
            }
            return index.TryGetValue(table + "|" + key, out var v) ? v : null;
        }
        void OnValidate() => index = null;
        [Tooltip("Steps the tutor leaves to Brann's existing lines on purpose (lines.json `silent`).")] public string[] silentSteps = new string[0];
        [Tooltip("SHA-1 of the lines.json this was generated from.")] public string sourceHash = "";

        public Line Find(string trigger) { if (string.IsNullOrEmpty(trigger)) return null; foreach (var l in lines) if (l.trigger == trigger) return l; return null; }
        public bool Has(string trigger) => Find(trigger) != null;

        /// The line in the bench voice's own form, so BenchVoice.SayLine speaks and captions it as one of Brann's.
        public static AssemblyAudioTable.Line ToVoice(Line l) => l == null ? null : new AssemblyAudioTable.Line { id = l.id, speaker = "npc_brann", trigger = l.trigger, text = l.text, clip = l.clip };
    }
}
